const {fitData} = DataScience;
const linear = NeuralNet.ACTIVATIONS.linear;
const nn = NeuralNet
.builder()
.input(2)
.layer(10)
.layer(10, NeuralNet.ACTIVATIONS.sigmoid)
.layer(1, linear)
.build();

const trainXs = NArray.range(0, 500).map(() => [3 * (2 * Math.random() - 1),3 * (2 * Math.random() - 1)]);
const testXs = NArray.range(0, 500).map(() => [3 * (2 * Math.random() - 1),3 * (2 * Math.random() - 1)]);
const sinc = (x,y) => Math.sin(x * x  + y * y) / (x * x + y * y);
const yf = ([x,y]) => sinc(x,y) + 0.1 * (2 * Math.random() - 1);

let {scene} = IO.plotPointCloud(trainXs.map(([x,y]) => [x, y, yf([x, y])]), {color:[1,0,0]});
const {theta} = fitData(trainXs, trainXs.map(yf), nn.model, {epochs: 10000, batch: 128, learningRate: 0.1, finiteDiff: true});
nn.setWeights(theta);
IO.plotPointCloud(testXs.map(([x,y]) => [x, y, nn.eval([x, y])]), {scene, color:[0,0,1]});
